{
  "findings": [
    {
      "check_id": "CKV_AZURE_41",
      "title": "Key Vault secret has no expiration date",
      "resource": "azurerm_key_vault_secret.database_connection_string",
      "severity": "MEDIUM",
      "explanation": "The database connection string contains privileged SQL credentials but has no expiration date, allowing the secret to remain valid indefinitely if it is not manually rotated or revoked."
    }
  ],
  "patched_code": "variable "database_connection_string_expiration_date" {
  description = "RFC3339 expiration date for the database connection string Key Vault secret."
  type        = string
}

resource "azurerm_key_vault_secret" "database_connection_string" {
  name            = "database-connection-string"
  value           = "Server=tcp:${azurerm_mssql_server.legal_sql_server.fully_qualified_domain_name},1433;Database=${azurerm_mssql_database.legal_metadata_db.name};User ID=${var.sql_admin_username};Password=${var.sql_admin_password};Encrypt=true;TrustServerCertificate=false;Connection Timeout=30;"
  key_vault_id    = azurerm_key_vault.legal_keyvault.id
  expiration_date = var.database_connection_string_expiration_date

  depends_on = [azurerm_mssql_database.legal_metadata_db]
}
",
  "fix_summary": "Added a required RFC3339 expiration-date variable and assigned it to the Key Vault secret so the database credential cannot remain valid indefinitely."
}
